<script setup lang="ts">
import WorkflowActionButtons from '@/components/WorkflowActionButtons.vue';
import WorkflowHistoryTimeline from '@/components/WorkflowHistoryTimeline.vue';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { AlertTriangle, ArrowLeft, CalendarClock, FileCheck2, Landmark, Pencil, Save, ShieldCheck, WalletCards, WandSparkles } from 'lucide-vue-next';
import { computed, ref } from 'vue';

type Dpa = {
    id: number; tahun: number; jenis_anggaran: 'murni' | 'perubahan'; type_label: string; judul: string;
    nomor_dpa?: string | null; tanggal_pengesahan?: string | null; status: string;
    nomor_perda_apbd?: string | null; tanggal_perda_apbd?: string | null;
    nomor_perkada_penjabaran?: string | null; tanggal_perkada_penjabaran?: string | null;
    nama_pengguna_anggaran?: string | null; nip_pengguna_anggaran?: string | null;
    nama_ppkd?: string | null; nip_ppkd?: string | null; nama_sekretaris_daerah?: string | null; nip_sekretaris_daerah?: string | null;
    catatan_verifikasi?: string | null;
    opd?: { kode?: string | null; nama: string; singkatan?: string | null } | null;
    opd_unit?: { kode?: string | null; nama: string } | null;
    rka?: { judul: string; nomor_dokumen?: string | null } | null;
    renja?: { judul: string } | null; rkpd?: { judul: string } | null;
};
type CashPlan = { bulan: number; jumlah: string | number };
type Row = {
    id: number; kode_program?: string | null; nama_program?: string | null; kode_kegiatan?: string | null; nama_kegiatan?: string | null;
    kode_sub_kegiatan?: string | null; nama_sub_kegiatan?: string | null; tolok_ukur_kinerja?: string | null;
    target_kinerja?: string | null; satuan_kinerja?: string | null; sumber_pendanaan?: string | null;
    lokasi?: string | null; kelompok_sasaran?: string | null; bulan_mulai: number; bulan_selesai: number;
    jenis_belanja?: string | null; pagu_rka: string | number; pagu_dpa: string | number;
    alasan_penyesuaian?: string | null; catatan?: string | null; urutan: number; cash_plan: CashPlan[];
};
type Readiness = { ready: boolean; issues: string[]; mismatched_items: number };
type WorkflowHistory = { id: number; action: string; from_status?: string | null; to_status: string; notes?: string | null; created_at: string; actor?: { name: string } | null };
type Workflow = { submitted_by?: number | null; histories?: WorkflowHistory[] } | null;

const props = defineProps<{
    dpa: Dpa; items: Row[];
    summary: { items_count: number; pagu_rka: number; pagu_dpa: number; monthly_totals: Record<number, number> };
    submissionReadiness: Readiness; approvalReadiness: Readiness; workflow: Workflow;
    can: { manage: boolean; verifyBudget: boolean; review: boolean; lock: boolean; unlock: boolean; withdraw: boolean };
}>();

const activeTab = ref<'rincian' | 'preview'>('rincian');
const editOpen = ref(false);
const editing = ref<Row | null>(null);
const itemForm = useForm({ pagu_dpa: 0 as string | number, alasan_penyesuaian: '', catatan: '', cash_plan: [] as CashPlan[] });
const months = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const rupiah = (value?: string | number | null) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value || 0));
const compactRupiah = (value: number) => new Intl.NumberFormat('id-ID', { notation: 'compact', maximumFractionDigits: 1 }).format(value);
const formatDate = (value?: string | null) => value ? new Intl.DateTimeFormat('id-ID', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Asia/Jakarta' }).format(new Date(`${value}T00:00:00+07:00`)) : '-';
const statusLabel = (status: string) => ({ draft: 'Draft', submitted: 'Diajukan', revision: 'Perlu Perbaikan', verified: 'Terverifikasi', approved: 'Disahkan', rejected: 'Ditolak', locked: 'Terkunci' })[status] ?? status;
const currentReadiness = computed(() => ['submitted', 'verified'].includes(props.dpa.status) ? props.approvalReadiness : props.submissionReadiness);
const currentReadinessTitle = computed(() => ['submitted', 'verified'].includes(props.dpa.status) ? 'DPA belum siap disahkan' : 'DPA belum siap diajukan');
const maxMonthly = computed(() => Math.max(...Object.values(props.summary.monthly_totals), 1));
const cashTotal = computed(() => itemForm.cash_plan.reduce((sum, item) => sum + Number(item.jumlah || 0), 0));
const cashDifference = computed(() => Number(itemForm.pagu_dpa || 0) - cashTotal.value);

const groupedPrograms = computed(() => {
    const programs = new Map<string, { key: string; kode: string; nama: string; kegiatan: Map<string, { key: string; kode: string; nama: string; items: Row[] }> }>();
    props.items.forEach((item) => {
        const programKey = `${item.kode_program || '-'}|${item.nama_program || '-'}`;
        if (!programs.has(programKey)) programs.set(programKey, { key: programKey, kode: item.kode_program || '-', nama: item.nama_program || 'Program belum terpetakan', kegiatan: new Map() });
        const program = programs.get(programKey)!;
        const activityKey = `${item.kode_kegiatan || '-'}|${item.nama_kegiatan || '-'}`;
        if (!program.kegiatan.has(activityKey)) program.kegiatan.set(activityKey, { key: activityKey, kode: item.kode_kegiatan || '-', nama: item.nama_kegiatan || 'Kegiatan belum terpetakan', items: [] });
        program.kegiatan.get(activityKey)!.items.push(item);
    });
    return [...programs.values()].map((program) => ({ ...program, kegiatan: [...program.kegiatan.values()] }));
});

const openEditor = (item: Row) => {
    editing.value = item; itemForm.clearErrors(); itemForm.pagu_dpa = item.pagu_dpa;
    itemForm.alasan_penyesuaian = item.alasan_penyesuaian ?? ''; itemForm.catatan = item.catatan ?? '';
    itemForm.cash_plan = months.map((_, index) => ({ bulan: index + 1, jumlah: item.cash_plan.find((plan) => plan.bulan === index + 1)?.jumlah ?? 0 }));
    editOpen.value = true;
};
const allocateEvenly = () => {
    if (!editing.value) return;
    const activeMonths = itemForm.cash_plan.filter((plan) => plan.bulan >= editing.value!.bulan_mulai && plan.bulan <= editing.value!.bulan_selesai);
    const totalCents = Math.round(Number(itemForm.pagu_dpa || 0) * 100);
    const baseCents = Math.floor(totalCents / activeMonths.length);
    let remainder = totalCents - baseCents * activeMonths.length;
    itemForm.cash_plan.forEach((plan) => {
        if (!activeMonths.some((active) => active.bulan === plan.bulan)) { plan.jumlah = 0; return; }
        const extra = remainder > 0 ? 1 : 0; plan.jumlah = (baseCents + extra) / 100; remainder -= extra;
    });
};
const saveItem = () => {
    if (!editing.value) return;
    itemForm.put(route('dpa-opd.items.update', { dpa_opd: props.dpa.id, item: editing.value.id }), { preserveScroll: true, onSuccess: () => { editOpen.value = false; editing.value = null; } });
};
</script>

<template>
    <Head :title="dpa.judul" />
    <div class="flex flex-col gap-5 p-4 sm:p-5">
        <section class="overflow-hidden rounded-2xl border border-slate-200 bg-card shadow-sm dark:border-slate-800">
            <div class="relative border-b border-slate-200 bg-[linear-gradient(116deg,#fff_0%,#f2faf7_62%,#e9f7f1_100%)] px-5 py-5 dark:border-slate-800 dark:bg-[linear-gradient(116deg,#0f172a_0%,#0b2427_62%,#0a302e_100%)] sm:px-6">
                <div class="absolute -right-12 -top-28 size-72 rounded-full bg-emerald-300/20 blur-3xl dark:bg-emerald-500/10"></div>
                <div class="relative flex flex-col gap-5 xl:flex-row xl:items-start xl:justify-between">
                    <div class="flex min-w-0 items-start gap-3.5"><Link :href="route('dpa-opd.index')" class="inline-flex size-10 shrink-0 items-center justify-center rounded-xl border border-slate-200 bg-white/80 text-slate-600 shadow-sm dark:border-slate-700 dark:bg-slate-900/80 dark:text-slate-300"><ArrowLeft class="size-4" /></Link><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><span class="rounded-md border border-emerald-200 bg-emerald-50 px-2 py-1 text-[10px] font-bold uppercase tracking-[.1em] text-emerald-700 dark:border-emerald-800 dark:bg-emerald-950/50 dark:text-emerald-200">{{ dpa.type_label }}</span><span class="rounded-full bg-slate-100 px-2.5 py-1 text-[11px] font-semibold text-slate-700 ring-1 ring-inset ring-slate-200 dark:bg-slate-800 dark:text-slate-200 dark:ring-slate-700">{{ statusLabel(dpa.status) }}</span></div><h1 class="mt-2 max-w-4xl text-xl font-bold leading-tight tracking-tight text-slate-950 dark:text-white sm:text-2xl">{{ dpa.judul }}</h1><p class="mt-1 text-sm text-slate-500">{{ dpa.nomor_dpa || 'Nomor DPA diisi saat pengesahan' }} · Tahun Anggaran {{ dpa.tahun }}</p></div></div>
                    <div class="flex flex-wrap items-center gap-2"><Link v-if="can.manage || can.verifyBudget" :href="route('dpa-opd.edit', dpa.id)" class="inline-flex h-10 items-center gap-2 rounded-lg border bg-white/80 px-3.5 text-sm font-semibold text-slate-700 hover:bg-white dark:border-slate-700 dark:bg-slate-900/80 dark:text-slate-200"><Pencil class="size-4" />{{ can.verifyBudget && !can.manage ? 'Pengesahan' : 'Edit dokumen' }}</Link><WorkflowActionButtons module="dpa_opd" :model-id="dpa.id" :status="dpa.status" :can-manage="can.manage" :can-review="can.review" :can-lock="can.lock" :can-unlock="can.unlock" :can-withdraw="can.withdraw" :show-verify="true" button-class="h-10 rounded-lg px-3.5" /></div>
                </div>
            </div>
            <div class="grid divide-y divide-slate-200 sm:grid-cols-3 sm:divide-x sm:divide-y-0 dark:divide-slate-800"><div class="flex items-center gap-3 px-5 py-4"><div class="flex size-9 items-center justify-center rounded-lg bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-200"><FileCheck2 class="size-4" /></div><div><p class="text-xs text-slate-500">Sub kegiatan</p><p class="font-bold tabular-nums text-slate-950 dark:text-white">{{ summary.items_count }}</p></div></div><div class="flex items-center gap-3 px-5 py-4"><div class="flex size-9 items-center justify-center rounded-lg bg-blue-50 text-blue-700 dark:bg-blue-950/50 dark:text-blue-300"><Landmark class="size-4" /></div><div><p class="text-xs text-slate-500">Pagu RKA</p><p class="font-bold tabular-nums text-slate-950 dark:text-white">{{ rupiah(summary.pagu_rka) }}</p></div></div><div class="flex items-center gap-3 px-5 py-4"><div class="flex size-9 items-center justify-center rounded-lg bg-emerald-50 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-300"><WalletCards class="size-4" /></div><div><p class="text-xs text-slate-500">Pagu DPA</p><p class="font-bold tabular-nums text-slate-950 dark:text-white">{{ rupiah(summary.pagu_dpa) }}</p></div></div></div>
        </section>

        <section v-if="!currentReadiness.ready && !['approved', 'locked'].includes(dpa.status)" class="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50/80 px-4 py-3.5 text-amber-950 dark:border-amber-900/70 dark:bg-amber-950/30 dark:text-amber-100"><div class="mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-lg bg-amber-100 text-amber-700 dark:bg-amber-900/60 dark:text-amber-300"><AlertTriangle class="size-4" /></div><div><p class="text-sm font-bold">{{ currentReadinessTitle }}</p><ul class="mt-1 grid gap-x-8 text-xs leading-5 text-amber-800 dark:text-amber-200 sm:grid-cols-2"><li v-for="issue in currentReadiness.issues" :key="issue" class="before:mr-2 before:content-['—']">{{ issue }}</li></ul></div></section>

        <section class="grid gap-px overflow-hidden rounded-2xl border border-slate-200 bg-slate-200 shadow-sm dark:border-slate-800 dark:bg-slate-800 lg:grid-cols-[1.15fr_.85fr]">
            <div class="bg-card p-5 sm:p-6"><div class="flex items-center gap-2"><Landmark class="size-4 text-emerald-700 dark:text-emerald-300" /><h2 class="font-bold text-slate-900 dark:text-white">Dasar Pelaksanaan Anggaran</h2></div><p class="mt-3 font-bold text-slate-950 dark:text-white">{{ dpa.opd?.kode }} · {{ dpa.opd?.nama }}</p><div class="mt-4 grid gap-3 text-sm sm:grid-cols-2"><div><p class="text-[10px] font-bold uppercase tracking-wide text-slate-400">Perda APBD</p><p class="mt-1 text-slate-700 dark:text-slate-200">{{ dpa.nomor_perda_apbd || 'Belum diisi' }}</p><p class="text-xs text-slate-500">{{ formatDate(dpa.tanggal_perda_apbd) }}</p></div><div><p class="text-[10px] font-bold uppercase tracking-wide text-slate-400">Perkada Penjabaran APBD</p><p class="mt-1 text-slate-700 dark:text-slate-200">{{ dpa.nomor_perkada_penjabaran || 'Belum diisi' }}</p><p class="text-xs text-slate-500">{{ formatDate(dpa.tanggal_perkada_penjabaran) }}</p></div></div><p class="mt-4 border-l-2 border-emerald-300 pl-3 text-xs leading-5 text-slate-500">Acuan: {{ dpa.rka?.judul || '-' }}</p></div>
            <div class="bg-card p-5 sm:p-6"><div class="flex items-center gap-2"><ShieldCheck class="size-4 text-emerald-700 dark:text-emerald-300" /><h2 class="font-bold text-slate-900 dark:text-white">Pengesahan</h2></div><dl class="mt-3 grid gap-3 text-sm sm:grid-cols-2"><div><dt class="text-[10px] font-bold uppercase tracking-wide text-slate-400">Pengguna Anggaran</dt><dd class="mt-1 font-medium text-slate-800 dark:text-slate-200">{{ dpa.nama_pengguna_anggaran || 'Belum diisi' }}</dd><dd class="text-xs text-slate-500">NIP {{ dpa.nip_pengguna_anggaran || '-' }}</dd></div><div><dt class="text-[10px] font-bold uppercase tracking-wide text-slate-400">PPKD</dt><dd class="mt-1 font-medium text-slate-800 dark:text-slate-200">{{ dpa.nama_ppkd || 'Belum diisi' }}</dd><dd class="text-xs text-slate-500">NIP {{ dpa.nip_ppkd || '-' }}</dd></div><div class="sm:col-span-2"><dt class="text-[10px] font-bold uppercase tracking-wide text-slate-400">Persetujuan Sekretaris Daerah</dt><dd class="mt-1 font-medium text-slate-800 dark:text-slate-200">{{ dpa.nama_sekretaris_daerah || 'Belum diisi' }}</dd><dd class="text-xs text-slate-500">NIP {{ dpa.nip_sekretaris_daerah || '-' }}</dd></div></dl></div>
        </section>

        <section class="overflow-hidden rounded-2xl border border-slate-200 bg-card shadow-sm dark:border-slate-800">
            <header class="flex items-center justify-between border-b border-slate-200 px-5 py-4 dark:border-slate-800 sm:px-6"><div><h2 class="font-bold text-slate-900 dark:text-white">Rencana Penarikan Dana</h2><p class="text-xs text-slate-500">Distribusi kas seluruh sub kegiatan per bulan.</p></div><CalendarClock class="size-5 text-emerald-700 dark:text-emerald-300" /></header>
            <div class="grid grid-cols-4 gap-px bg-slate-200 dark:bg-slate-800 sm:grid-cols-6 xl:grid-cols-12"><div v-for="(month, index) in months" :key="month" class="flex min-h-28 flex-col justify-end bg-card px-3 py-3"><p class="mb-auto truncate text-[10px] font-bold uppercase tracking-wide text-slate-400">{{ month.slice(0, 3) }}</p><div class="mt-3 flex h-10 items-end"><div class="w-full rounded-t bg-emerald-400/70 dark:bg-emerald-500/60" :style="{ height: `${Math.max(4, (Number(summary.monthly_totals[index + 1] || 0) / maxMonthly) * 40)}px` }"></div></div><p class="mt-2 truncate text-[10px] font-semibold tabular-nums text-slate-600 dark:text-slate-300" :title="rupiah(summary.monthly_totals[index + 1])">{{ compactRupiah(Number(summary.monthly_totals[index + 1] || 0)) }}</p></div></div>
        </section>

        <section class="overflow-hidden rounded-2xl border border-slate-200 bg-card shadow-sm dark:border-slate-800">
            <header class="flex flex-col gap-3 border-b border-slate-200 px-5 py-4 dark:border-slate-800 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div><h2 class="font-bold text-slate-900 dark:text-white">Rincian DPA-BELANJA SKPD</h2><p class="text-xs text-slate-500">Pagu pelaksanaan dan penarikan dana per sub kegiatan.</p></div><div class="inline-flex self-start rounded-lg bg-slate-100 p-1 dark:bg-slate-800"><button type="button" class="rounded-md px-3 py-1.5 text-xs font-semibold" :class="activeTab === 'rincian' ? 'bg-white text-emerald-800 shadow-sm dark:bg-slate-950 dark:text-emerald-300' : 'text-slate-500'" @click="activeTab = 'rincian'">Rincian</button><button type="button" class="rounded-md px-3 py-1.5 text-xs font-semibold" :class="activeTab === 'preview' ? 'bg-white text-emerald-800 shadow-sm dark:bg-slate-950 dark:text-emerald-300' : 'text-slate-500'" @click="activeTab = 'preview'">Preview tabel</button></div></header>
            <div v-if="activeTab === 'rincian'" class="divide-y divide-slate-200 dark:divide-slate-800">
                <div v-for="program in groupedPrograms" :key="program.key" class="p-5 sm:p-6"><div class="flex items-start gap-3 border-b border-slate-200 pb-4 dark:border-slate-800"><span class="mt-0.5 rounded-md bg-[#064e3b] px-2 py-1 font-mono text-[11px] font-bold text-white">{{ program.kode }}</span><div><p class="text-[10px] font-bold uppercase tracking-[.14em] text-slate-400">Program</p><h3 class="mt-0.5 font-bold leading-6 text-slate-900 dark:text-white">{{ program.nama }}</h3></div></div><div v-for="activity in program.kegiatan" :key="activity.key" class="mt-5 border-l border-emerald-200 pl-4 dark:border-emerald-900"><div class="flex items-start gap-2"><span class="font-mono text-xs font-bold text-emerald-700 dark:text-emerald-300">{{ activity.kode }}</span><p class="text-sm font-semibold text-slate-800 dark:text-slate-200">{{ activity.nama }}</p></div><div class="mt-3 divide-y divide-slate-100 overflow-hidden rounded-xl border border-slate-200 dark:divide-slate-800 dark:border-slate-800"><article v-for="item in activity.items" :key="item.id" class="grid gap-4 bg-card px-4 py-4 lg:grid-cols-[minmax(14rem,1.3fr)_minmax(11rem,.8fr)_minmax(10rem,.7fr)_auto] lg:items-center"><div><p class="font-mono text-[11px] font-bold text-emerald-700 dark:text-emerald-300">{{ item.kode_sub_kegiatan }}</p><p class="mt-1 text-sm font-semibold leading-5 text-slate-900 dark:text-white">{{ item.nama_sub_kegiatan }}</p><p class="mt-1 text-xs text-slate-500">{{ months[item.bulan_mulai - 1] }}–{{ months[item.bulan_selesai - 1] }}</p></div><div><p class="text-[10px] font-bold uppercase tracking-wide text-slate-400">Target Kinerja</p><p class="mt-1 line-clamp-2 text-sm text-slate-700 dark:text-slate-200">{{ item.tolok_ukur_kinerja || '-' }}</p><p class="mt-1 text-xs font-semibold text-emerald-700 dark:text-emerald-300">{{ item.target_kinerja || '-' }} {{ item.satuan_kinerja || '' }}</p></div><div><p class="text-[10px] font-bold uppercase tracking-wide text-slate-400">Pagu DPA</p><p class="mt-1 text-sm font-bold tabular-nums text-slate-950 dark:text-white">{{ rupiah(item.pagu_dpa) }}</p><p class="mt-1 text-[10px] text-slate-500">RKA {{ rupiah(item.pagu_rka) }}</p></div><button v-if="can.manage || can.verifyBudget" type="button" class="inline-flex size-9 items-center justify-center rounded-lg border text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800" title="Atur rencana penarikan" @click="openEditor(item)"><Pencil class="size-4" /></button></article></div></div></div>
                <div v-if="!items.length" class="px-6 py-16 text-center text-sm text-slate-500">Tidak ada rincian sub kegiatan.</div>
            </div>
            <div v-else class="p-4 sm:p-6"><div class="mb-5 text-center"><p class="text-sm font-bold uppercase tracking-[.12em] text-slate-900 dark:text-white">Dokumen Pelaksanaan Anggaran</p><p class="text-sm font-bold uppercase tracking-[.12em] text-slate-900 dark:text-white">Satuan Kerja Perangkat Daerah</p><span class="mt-2 inline-flex rounded-md border border-slate-300 px-3 py-1 text-xs font-bold dark:border-slate-700">Formulir {{ dpa.type_label === 'DPPA-SKPD' ? 'DPPA-BELANJA SKPD' : 'DPA-BELANJA SKPD' }}</span><p class="mt-2 text-xs text-slate-500">Pemerintah Kabupaten Banjarnegara · Tahun Anggaran {{ dpa.tahun }}</p></div><div class="overflow-x-auto rounded-xl border border-slate-300 dark:border-slate-700"><table class="min-w-[1900px] border-collapse text-xs"><thead class="bg-slate-100 text-[10px] uppercase tracking-wide text-slate-600 dark:bg-slate-900 dark:text-slate-300"><tr><th class="border-b border-r p-3 text-left">Kode</th><th class="min-w-72 border-b border-r p-3 text-left">Urusan / Program / Kegiatan / Sub Kegiatan</th><th class="min-w-60 border-b border-r p-3 text-left">Indikator dan Tolok Ukur Kinerja</th><th class="border-b border-r p-3">Target Kinerja</th><th class="min-w-40 border-b border-r p-3 text-left">Sumber Pendanaan</th><th class="min-w-40 border-b border-r p-3 text-left">Lokasi / Kelompok Sasaran</th><th class="border-b border-r p-3 text-right">Pagu DPA</th><th v-for="month in months" :key="month" class="border-b border-r p-2 text-right">{{ month.slice(0, 3) }}</th></tr></thead><tbody class="divide-y divide-slate-200 dark:divide-slate-800"><tr v-for="item in items" :key="item.id" class="align-top"><td class="border-r p-3 font-mono font-bold text-emerald-700 dark:text-emerald-300">{{ item.kode_sub_kegiatan }}</td><td class="border-r p-3"><p class="font-semibold text-slate-900 dark:text-white">{{ item.nama_sub_kegiatan }}</p><p class="mt-1 text-[10px] text-slate-500">{{ item.kode_program }} · {{ item.nama_program }}</p><p class="text-[10px] text-slate-500">{{ item.kode_kegiatan }} · {{ item.nama_kegiatan }}</p></td><td class="border-r p-3 leading-5">{{ item.tolok_ukur_kinerja || '-' }}</td><td class="border-r p-3 text-center font-semibold">{{ item.target_kinerja || '-' }} {{ item.satuan_kinerja || '' }}</td><td class="border-r p-3">{{ item.sumber_pendanaan || '-' }}</td><td class="border-r p-3"><p>{{ item.lokasi || '-' }}</p><p class="mt-1 text-[10px] text-slate-500">Sasaran: {{ item.kelompok_sasaran || '-' }}</p></td><td class="border-r p-3 text-right font-bold tabular-nums">{{ rupiah(item.pagu_dpa) }}</td><td v-for="month in months.map((_, index) => index + 1)" :key="month" class="border-r p-2 text-right tabular-nums">{{ rupiah(item.cash_plan.find((plan) => plan.bulan === month)?.jumlah || 0) }}</td></tr></tbody><tfoot class="bg-slate-50 font-bold dark:bg-slate-900"><tr><td colspan="6" class="border-t border-r p-3 text-right">Jumlah Anggaran Belanja</td><td class="border-t border-r p-3 text-right">{{ rupiah(summary.pagu_dpa) }}</td><td v-for="month in months.map((_, index) => index + 1)" :key="month" class="border-t border-r p-2 text-right">{{ rupiah(summary.monthly_totals[month]) }}</td></tr></tfoot></table></div></div>
        </section>

        <WorkflowHistoryTimeline :workflow="workflow" />
    </div>

    <Dialog v-model:open="editOpen">
        <DialogContent class="max-h-[94vh] overflow-y-auto sm:max-w-5xl"><DialogHeader><DialogTitle>Rencana Penarikan Dana</DialogTitle><DialogDescription>{{ editing?.kode_sub_kegiatan }} · {{ editing?.nama_sub_kegiatan }}</DialogDescription></DialogHeader><form class="mt-2 grid gap-5" @submit.prevent="saveItem"><div class="grid gap-4 rounded-xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-800 dark:bg-slate-900/60 sm:grid-cols-2"><div><p class="text-[10px] font-bold uppercase tracking-wide text-slate-400">Pagu RKA disetujui</p><p class="mt-1 font-bold tabular-nums text-slate-900 dark:text-white">{{ rupiah(editing?.pagu_rka) }}</p></div><label><span class="text-[10px] font-bold uppercase tracking-wide text-emerald-700">Pagu DPA</span><input v-model="itemForm.pagu_dpa" :disabled="!can.verifyBudget" inputmode="numeric" class="mt-1.5 h-10 w-full rounded-lg border border-emerald-300 bg-background px-3 text-sm font-semibold tabular-nums disabled:border-slate-200 disabled:opacity-70 dark:border-emerald-800" /></label></div><div><div class="mb-3 flex flex-wrap items-center justify-between gap-3"><div><h3 class="text-sm font-bold text-slate-900 dark:text-white">Penarikan per bulan</h3><p class="text-xs text-slate-500">Hanya bulan dalam waktu pelaksanaan yang dapat diisi.</p></div><button type="button" class="inline-flex h-9 items-center gap-2 rounded-lg border px-3 text-xs font-semibold hover:bg-slate-50 dark:hover:bg-slate-800" @click="allocateEvenly"><WandSparkles class="size-3.5" />Bagi rata</button></div><div class="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4"><label v-for="(plan, index) in itemForm.cash_plan" :key="plan.bulan" class="rounded-xl border p-3" :class="editing && plan.bulan >= editing.bulan_mulai && plan.bulan <= editing.bulan_selesai ? 'border-slate-200 dark:border-slate-700' : 'border-slate-100 bg-slate-50 opacity-50 dark:border-slate-800 dark:bg-slate-900'"><span class="text-[10px] font-bold uppercase tracking-wide text-slate-500">{{ months[index] }}</span><input v-model="plan.jumlah" :disabled="!!editing && (plan.bulan < editing.bulan_mulai || plan.bulan > editing.bulan_selesai)" inputmode="numeric" class="mt-1.5 h-9 w-full rounded-lg border bg-background px-2 text-right text-xs tabular-nums disabled:cursor-not-allowed" /></label></div><p v-if="itemForm.errors.cash_plan" class="mt-2 text-xs text-red-600">{{ itemForm.errors.cash_plan }}</p></div><div class="flex flex-col gap-2 rounded-xl px-4 py-3 sm:flex-row sm:items-center sm:justify-between" :class="Math.abs(cashDifference) <= .01 ? 'bg-emerald-50 text-emerald-900 dark:bg-emerald-950/40 dark:text-emerald-200' : 'bg-amber-50 text-amber-900 dark:bg-amber-950/40 dark:text-amber-200'"><span class="text-xs font-semibold">Total penarikan {{ rupiah(cashTotal) }}</span><span class="text-xs font-bold">{{ Math.abs(cashDifference) <= .01 ? 'Sesuai pagu DPA' : `Selisih ${rupiah(cashDifference)}` }}</span></div><div class="grid gap-4 sm:grid-cols-2"><label><span class="text-xs font-bold uppercase tracking-wide text-slate-500">Alasan Penyesuaian Pagu</span><textarea v-model="itemForm.alasan_penyesuaian" rows="3" class="mt-1.5 w-full rounded-xl border bg-background p-3 text-sm" placeholder="Wajib jika pagu berbeda dari RKA."></textarea><span v-if="itemForm.errors.alasan_penyesuaian" class="mt-1 block text-xs text-red-600">{{ itemForm.errors.alasan_penyesuaian }}</span></label><label><span class="text-xs font-bold uppercase tracking-wide text-slate-500">Keterangan</span><textarea v-model="itemForm.catatan" rows="3" class="mt-1.5 w-full rounded-xl border bg-background p-3 text-sm"></textarea></label></div><div class="flex justify-end gap-2 border-t pt-4"><button type="button" class="h-10 rounded-lg border px-4 text-sm font-semibold hover:bg-slate-50 dark:hover:bg-slate-800" @click="editOpen = false">Batal</button><button type="submit" :disabled="itemForm.processing || Math.abs(cashDifference) > .01" class="inline-flex h-10 items-center gap-2 rounded-lg bg-[#064e3b] px-4 text-sm font-semibold text-white hover:bg-[#043d2e] disabled:opacity-50"><Save class="size-4" />{{ itemForm.processing ? 'Menyimpan...' : 'Simpan Rencana' }}</button></div></form></DialogContent>
    </Dialog>
</template>
